# coding: utf-8
from lesson_authoring import entry as E
from author_batch200_root_mis_b import M
WF=[
E('misrule','/ˌmɪsˈruːl/','治理不善；暴政；混乱的统治','负责管理的人把事情管坏了，受影响的是整个地方或机构。','mis- + rule“治理、统治”；不是“没有一条规则”。',M+[['中古英语 mis- + rule','错误或恶劣的治理'],['英语 misrule','治理不善、混乱或暴虐的统治']],'misrule 常出现在历史、政治评论里，概括长期失政或混乱的统治。它是带批评色彩的词，既可能着重无能，也可能着重恶劣和压迫，需要看文章具体说了什么。','years of misrule；corruption and misrule；suffer under misrule。','misrule 说治理本身出了问题；disorder 是混乱状态，混乱可以有多种原因，不一定都来自统治。',('The historian describes decades of corruption and misrule.','历史学家描述了数十年的腐败与失政。'),('The novel is set in a province exhausted by years of misrule.','小说以一个因多年失政而疲敝的省份为背景。'),sources=['https://en.wiktionary.org/wiki/misrule','https://www.etymonline.com/word/misrule']),
E('miscast','英 /ˌmɪsˈkɑːst/；美 /ˌmɪsˈkæst/','给演员安排不合适的角色；把人放错角色或位置','人未必没有能力，但让他演的那一位，或承担的那种身份，和他不合。','mis- + cast；cast 的“分配角色”义带来现代常用法，早期 miscast 还有别的意思。',M+[['英语 mis- + cast，早期有投射、计算失当等用法','随着 cast 的意义扩展而发展'],['cast 用于分配戏剧角色 → miscast','安排了不合适的角色']],'an actor is miscast 是说角色安排不合适，不必等于演员演技差。它也能用于工作或舆论中的身份安排，比如把一个调解者硬当成强硬谈判者。过去式、过去分词仍写 miscast。','be miscast as someone；be badly miscast；a miscast actor。','miscast 说角色匹配有问题；underperform 说实际表现低于预期。角色合适的人也可能发挥不好。',('The reviewer thought the actor was miscast as the young prince.','评论者认为让那位演员饰演年轻王子不合适。'),('She felt miscast in a role that required constant confrontation.','她觉得让自己承担一个需要不断与人对抗的角色很不合适。'),sources=['https://www.etymonline.com/word/miscast','https://en.wiktionary.org/wiki/miscast']),
E('misapprehension','/ˌmɪsæprɪˈhenʃən/','误解；错误认识〔较正式〕','你心里已经“抓住”了一个解释，但抓住的是错的。','mis- + apprehension；apprehension 在这里是理解、领会，不是担心。',M+[['apprehension 的“理解”义加 mis-','对事实或意思理解不对'],['英语 misapprehension','一种错误认识']],'be under the misapprehension that... 很常用，意思是“误以为……”。这个词常出现在正式澄清里，指出某人当前依据的认识有误。看见 apprehension 不要只背“忧虑”，否则就会误译成“不正确的害怕”。','be under the misapprehension that...；correct a misapprehension；a common misapprehension。','misapprehension 比 misunderstanding 正式，常突出错误信念；apprehensive 则通常表示担忧，不能逐个字母照搬过去。',('I was under the misapprehension that the fee included meals.','我误以为费用里已经包含餐食。'),('Let me correct one common misapprehension about the project.','我来澄清一下大家对这个项目常有的一种误解。'),sources=['https://www.etymonline.com/word/misapprehension','https://en.wiktionary.org/wiki/misapprehension']),
E('mistranslation','/ˌmɪstrænzˈleɪʃən/，也读 /ˌmɪstrænsˈleɪʃən/','误译；错误的译文或译法','内容从一种语言搬到另一种语言时，意思在途中走样了。','mis- + translation；现代构词表示翻译中的错误。',M+[['英语 translation 加 mis-','翻译不准确'],['mistranslation','误译行为，或某一处错误译法']],'mistranslation 可以指词义选错，也可以指否定、语气或关系翻错。一句译文即使读起来非常流畅，也可能是 mistranslation；好读与忠实传达原意是两件事。','a mistranslation of a phrase；correct a mistranslation；a misleading mistranslation。','misspelling 是字母拼错；mistranslation 是跨语言传达错。misinterpretation 则不要求跨语言。',('A mistranslation made the polite request sound like an order.','一处误译把礼貌的请求变成了命令的语气。'),('The new edition corrects several mistranslations.','新版改正了几处误译。'),sources=['https://www.merriam-webster.com/dictionary/mistranslation','https://en.wiktionary.org/wiki/mistranslation']),
E('misidentification','/ˌmɪsaɪdentɪfɪˈkeɪʃən/','认错；错误识别；身份或类别误判','本来是甲，却给它贴上了乙的名字、身份或类别。','mis- + identification；后者表示辨认、确认身份或类别。',M+[['英语 identification 加 mis-','辨认有误'],['misidentification','认错人、物或所属类别']],'misidentification 可以是目击者认错人，也可以是软件认错图片中的物体，或把一种植物当成另一种。重点是“这究竟是谁、是什么”的判断错了，而不只是描述有一点不够详细。','mistaken identity and misidentification；misidentification of a species；a case of misidentification。','misclassification 侧重分错类别；misidentification 也可以是认错具体的个人或物件。两者在分类任务中会重叠。',('The museum corrected the misidentification of the bird in the photograph.','博物馆更正了对照片中那只鸟的错误识别。'),('The study examines cases of eyewitness misidentification.','这项研究考察了目击者认错人的案例。'),sources=['https://en.wiktionary.org/wiki/misidentification','https://www.merriam-webster.com/dictionary/misidentification']),
E('misquote','英 /ˌmɪsˈkwəʊt/；美 /ˌmɪsˈkwoʊt/','错误引用；误引；把原话引错','声称是在重复别人的原话，重复出来的内容却不对。','mis- + quote“引用”；不是单纯不赞同那句话。',M+[['英语 mis- + quote','引用有误'],['misquote','引错原话，或歪曲地转述为原话']],'misquote someone 可以是漏掉一个关键的 not，也可以是把不同句子拼成原话没有表达的意思。不是所有概括都叫 misquote：概括可以用自己的话，关键在有没有错误地当作引用。','misquote a speaker；be misquoted in the press；misquote a sentence。','misquote 是引错；paraphrase 是换个说法转述，可以准确也可以不准确。不同意某句话本身不是 misquote。',('The article misquoted her by leaving out the word “not.”','文章漏掉了 not 这个词，因而错误引用了她的话。'),('He checked the recording to make sure he had not misquoted the speaker.','他核对了录音，确认自己没有引错发言者的话。'),sources=['https://en.wiktionary.org/wiki/misquote','https://www.etymonline.com/word/misquote']),
E('misdiagnosis','英 /ˌmɪsˌdaɪəɡˈnəʊsɪs/；美 /ˌmɪsˌdaɪəɡˈnoʊsɪs/','误诊；错误的诊断或问题判断','看到了症状，却给它安上了不正确的病因或问题名称。','mis- + diagnosis“诊断”；diagnosis 本身来自希腊的辨别、认识这一支，不代表 mis- 也变成了希腊词根。',M+[['英语 diagnosis 加 mis-','诊断发生错误'],['misdiagnosis','错误诊断；也可比喻对问题原因的误判']],'misdiagnosis 常用于医疗阅读，表示诊断错了；也可以比喻公司对业务问题的判断有误。它说的是诊断结果，不是所有治疗不顺或设备故障的统称。复数是 misdiagnoses，尾音读 /siːz/。','an initial misdiagnosis；correct a misdiagnosis；a misdiagnosis of the problem。','diagnosis 是诊断，misdiagnosis 是误诊。delayed diagnosis 是诊断延迟，和判断错不是同一个概念。',('The later tests revealed that the initial diagnosis had been a misdiagnosis.','后来的检查表明，最初的诊断是误诊。'),('The manager’s misdiagnosis of the problem led to an ineffective solution.','经理误判了问题的原因，导致解决方案没有效果。'),sources=['https://www.merriam-webster.com/dictionary/misdiagnosis','https://en.wiktionary.org/wiki/misdiagnosis']),
]
